              "tip2": "记录他们告诉你的所有内容——询问与你交谈的人的姓名",
              "tip3": "要求以书面形式提供任何说明，或告知他们你将在线跟进",
              "tip4": "将你了解到的信息告知你的律师——这可能影响案件策略"
