          "question": "房东可以因为我被逮捕而驱逐我吗？",
          "answer": "在大多数情况下，仅仅被逮捕不是驱逐的有效理由。大多数租约要求刑事定罪，即便如此，也只有当其与影响房产或其他租客的行为有关时才适用。房东必须通过法院遵循正式驱逐程序——未经法院命令，他们不能驱逐你、更换锁具或切断水电。查阅你的租约并在收到任何通知时联系房客法律援助组织。"
