              "tip2": "你永远不必分享超出你舒适范围的内容——'我现在无法详细说明'是一个完整的句子",
              "tip3": "指控是指控，不是定罪——你有权清晰准确地这样说",
              "tip4": "对话结束后，写下所说的内容和时间——尤其是在可能日后相关的职业场合"
