      "immigrationSummary": "**移民执法信息**\n\n如果您担心移民执法，以下是法律上重要的内容。\n\n**沉默权：** 该权利适用于有关移民身份的问题。人们没有义务回答关于出生地、入境方式或移民身份的问题。\n\n**律师权：** 该权利在移民程序中存在。在回答问题或签署文件之前咨询律师通常是明智的。\n\n**家庭入境：** 移民官员通常需要法官签署的司法令状才能进入住宅。ICE行政令（I-200表格）不具有相同的权威。\n\n**文件：** 在未经法律审查的情况下签署文件可能放弃权利。处于这种情况的人通常在签署任何文件之前咨询律师会更有益。\n\n如需全面的移民指导，请访问我们的 [移民指导](/immigration-guidance) 页面。\n\n**还有什么我可以帮您的？**",
