        "atHome": "🏠 **您在家中的权利：**\n\n• 进入住宅通常需要法官签署的司法令状。ICE行政令（I-200表格）不具有相同的权威。\n• 在门口声明不同意入室是对权利的法律认可主张。\n• 如果官员在没有司法令状的情况下进入，这与任何后续法律挑战相关。\n• 官员姓名和警号等信息通常对审查该事件的律师很有帮助。\n\n📞 **紧急联系方式：**\n• National Immigration Forum: 1-800-954-6287\n• ACLU: 发短信 \"IMMIGRANT\" 到 88823\n\n**立即联系移民律师：**",
        "atWork": "💼 **您在工作场所的权利：**\n\n• 沉默权适用于与移民当局的工作场所接触。\n• 令状应指明地点和其所涵盖人员的姓名。仔细阅读很重要。\n• 接触期间所做的陈述可用于移民程序。\n• 有关移民身份的问题不必回答。\n• 律师可在询问期间在场。\n\n📋 您的雇主不能因为您行使权利而报复您。\n\n**了解更多关于工作场所突袭和雇主责任的信息：**",
        "inPublic": "🚶 **您在公共场所/检查站的权利：**\n\n• 有关移民身份的沉默权适用于公共场所的接触。\n• 在移民检查站，可能会被问到公民身份。沉默权仍然适用。\n• 保持冷静有助于维护安全并为日后法律挑战保留选择。\n• 如果被拘留，与律师交谈的权利适用。\n\n📞 **紧急联系方式：**\n• National Immigration Forum: 1-800-954-6287\n• DOJ Immigration Review: 1-800-898-7180\n\n**联系移民律师：**"
