        "myself": "个人准备方面，请考虑：\n\n• 在任何接触之前**了解您的权利**\n• **准备一张紧急联系卡** 上面有律师信息\n• **将重要文件** 保存在安全且方便取用的地方\n• **制定家庭沟通计划**\n\n如果您有 DACA、TPS 或其他受保护身份，请关注续期和截止日期：",
