      "firstAppearanceStateCA": "首次出庭通常在48小时内（不含周末/节假日）。Humphrey案（2021年）后：法院在设定保释金前必须考虑支付能力。",
      "firstAppearanceStateNY": "在纽约州，起诉即为首次出庭——纽约市通常在24小时内，上州在24至48小时内。保释改革（2020年）：大多数轻罪和许多非暴力重罪无需保释。",
      "firstAppearanceStateTX": "裁定必须在48小时内进行。治安法官根据法定因素（德克萨斯刑事诉讼法典第17.15条）确定初始保释金。",
      "firstAppearanceStateFL": "在24小时内于县法官面前首次出庭。法官须告知指控、确定保释金并指定律师。",
      "firstAppearanceStateFed": "在联邦治安法官面前的初次出庭须'无不必要延迟'——法院将其解释为48小时内。"
