      "targetLetterContext": "目标信意味着大陪审团正将您作为可能的被告展开调查。您现在拥有的选择比正式起诉后要多——但时间窗口正在缩小。",
      "targetLetterDo1": "立即联系刑事辩护律师。不要等待。",
