      "warrantContext": "如果您知道存在逮捕令，您仍然有选择。在自己的条件下——由律师陪同——主动投案，通常比意外被捕产生更好的结果。",
      "warrantDo1": "在采取任何行动之前，先联系刑事辩护律师。",
