      "probationParoleC3Title": "违规标准",
      "probationParoleC3": "仅凭逮捕就可以触发违规听证——不需要在新指控上定罪。违规听证的证明标准低于刑事审判。",
      "probationParoleC4Title": "向监督官的陈述",
