      "probationParoleDo1": "立即告诉您的律师您处于缓刑或假释状态。这会影响新指控和违规程序的策略。",
      "probationParoleDo2": "询问律师是否会有监督令阻止您获释，即使新指控已设定保释金。这是两种不同的羁押令，必须分别处理。",
