        "do2": "告诉他们：(1) 设施名称，(2) 您的案件编号，(3) 如果知道的话告知指控内容，(4) 请他们找私人律师，或如有费用顾虑，联系您被捕所在县的公设辩护人办公室了解法院指派程序。",
        "do3": "保持通话简短实用。通话时间越长，录音材料越多。",
        "do4": "请家人记下一切内容，并立即开始寻找法律援助。",
