        "c4Title": "不要讨论的内容",
        "c4": "这通电话不是描述案件经过、讨论证据或与案件相关人员协调的场合。此类对话不受保护，并将成为记录的一部分。",
        "dont6": "不要以为从看守所发出的信件、短信或电子邮件比电话更私密。它们同样不私密。"
