        "bail2": "申请降低保释金：您的律师可以论证保释金相对于您的收入而言过高。法院有义务考虑您的支付能力。",
        "bail3": "保释基金：为无力支付保释金的人支付保释金的非营利组织。搜索「[您的城市] 保释基金」或咨询您的律师。案件结束后，资金通常会被循环利用。",
        "bail4": "保释保证公司：保证人以不可退还的费用（通常为10-15%）支付您的全部保释金。警告：如果您错过庭审，保证人可以追查您并没收您提供的任何抵押品。",
        "bail5": "房产担保：以房屋净值作为抵押替代现金。风险：如果您错过听证，法院可能对该房产设置留置权。",
