        "c4Title": "如果继续被羁押",
        "c4": "如果您继续被羁押，律师可以申请降低保释金的听证。这是一个重要的早期步骤，应在律师被联系后尽快提出。",
        "bail6": "暂时继续被羁押。有时，到起诉的时间足够短，争取释放的重要性相对较低。请与您的律师讨论。"
