          "layerContracted": "一些较小的城市将某些案件的起诉工作外包给私人律师事务所。您的律师可以通过案件编号和庭审文件迅速确认这一点。",
          "whyMatters": "每个办公室有不同的辩诉交易政策、不同的分流项目和不同的工作人员。您的律师需要知道是哪个办公室受理您的案件，才能评估您的选项。",
          "action": "将文件上检察机构的确切名称告诉您的律师。如果您还没有文件，一旦有了案件编号，律师可以帮您查询。"
