    "overview": {
      "title": "概述",
      "body": "本页面涵盖驱逐后的实际情况，而非法律程序本身。无论驱逐以何种方式发生，均适用于此页面。面临这种情况的人通常同时面临两个挑战：被驱逐者需要在新地点安置，而留守家庭则面临财务和后勤方面的困扰。"
    },
    "ifDeported": {
      "sectionTitle": "如果您被驱逐",
      "first72": {
        "title": "前72小时",
        "step1Title": "寻找通讯方式",
        "step1Body": "图书馆、教堂、庇护所和移民庇护所（casas del migrante）通常提供免费WiFi。WhatsApp、Signal和Google Voice可通过WiFi进行免费国际通话。",
        "step2Title": "联系最近的美国大使馆或领事馆",
        "step2Body": "他们可以帮助美国公民家庭成员联系到您，如有需要还可为您提供遣返资源。",
        "step3Title": "联系移民庇护所",
        "step3Body": "Casas del Migrante及类似庇护所遍布墨西哥和中美洲大多数主要城市。通常提供紧急住所、食物、定向指导和帮助寻找服务。无需任何移民身份即可使用。",
        "step4Title": "联系Al Otro Lado",
        "step4Body": "如果您被驱逐到墨西哥或中美洲，Al Otro Lado在边境两侧均有工作人员和法律支持。他们专门服务于被驱逐的长期美国居民。"
      },
      "grewUpInUs": {
        "title": "如果您在美国长大",
        "body": "有些人被驱逐到他们成年后只短暂居住或从未居住过的国家。这种情况下，人们通常面临语言障碍、缺乏社会网络以及不熟悉当地体系等挑战。Al Otro Lado等机构专门与被驱逐的长期美国居民合作，可帮助定向指导、语言获取和联系当地服务。美国大使馆有时可以转介口译服务。"
      },
      "documents": {
        "title": "获取文件",
        "item1": "您出生国的出生证明是在该国建立身份的基本文件。民政登记处（西班牙语国家称为registro civil）负责出具经认证的副本。",
        "item2": "如果您有在美国出生的子女，他们的美国出生证明或护照可证明该关系，可能与未来的程序相关。",
        "item3": "对于墨西哥：外交关系部（SRE）可以帮助墨西哥公民获得领事文件，即使他们没有出生证明。",
        "note": "所需文件因国家而异。当地民政登记处或移民庇护所可就具体流程提供建议。"
      },
      "money": {
        "title": "从美国家人处接收汇款",
        "item1": "Western Union、MoneyGram和Remitly都提供国际汇款服务，可在大多数国家的药店、便利店和银行取现。",
        "item2": "Wise（前身为TransferWise）对定期汇款通常收费更低，可直接存入银行账户。",
        "item3": "取现需要政府颁发的身份证件。您的出生证明或任何带有照片和姓名的文件通常可作为开始使用的凭证。",
        "item4": "加密货币和稳定币（如USDC或USDT）被一些处于这种情况的人用于跨境转账，特别是在传统服务覆盖有限的地方。考虑此选项的人通常会审查所使用平台的服务条款。美国和目的地国家对加密货币交易的法律各不相同，这些差异可能会影响转账的处理方式。"
      }
    },
    "familyInUs": {
      "sectionTitle": "如果您的家人在美国",
      "contact": {
        "title": "保持联系",
        "item1": "WhatsApp和Signal都是可通过WiFi使用的免费国际通讯和通话应用。Signal采用端对端加密，意味着消息和通话只有发送方和接收方才能读取。如果您还没有被驱逐者的联系方式，可以请他们一到庇护所或图书馆就通过WiFi联系您。",
        "item2": "Al Otro Lado专门设有驱逐后跨境联系的家庭团聚热线。",
        "item3": "您家人所在目的地国在美国的领事馆有时可以在驱逐后的紧急情况下协助寻找家庭成员。",
        "item4": "Google Voice提供一个免费的美国电话号码，可通过WiFi接听国际电话。如果被驱逐者尚未有当地SIM卡，这非常实用。"
      },
      "financial": {
        "title": "紧急财务援助",
        "item1": "211（拨打电话或发短信）：连接当地紧急财务援助、食物银行、租金帮助和公用事业援助。全美各地均可使用。",
        "item2": "SNAP（食品援助）：混合移民身份家庭中的美国公民子女，即使父母被驱逐后通常仍有资格获得SNAP福利。资格认定基于子女的身份，而非父母的身份。",
        "item3": "大多数县都有紧急租房援助计划。可通过全国低收入住房联盟（nlihc.org）搜索或拨打211。",
        "item4": "当地互助网络和社区基金会通常为危机中的家庭维持快速响应基金。搜索您所在城市名称加上'mutual aid'或'immigrant community fund'通常可找到当地选项。"
      },
      "children": {
        "title": "子女与学校",
        "item1": "在美国出生的子女有权留在美国并继续就读公立学校。学校通常不得询问学生或家长的移民身份。",
        "item2": "如果父母被驱逐后美国出生的子女在美国没有监护人，学校辅导员可以将家庭联系到儿童福利和支持资源。",
        "item3": "选择随被驱逐父母出国的子女通常保留其美国国籍。他们可以随时作为美国公民返回美国。",
        "item4": "如果驱逐后由非父母的人照看美国出生的子女，父母出具的监护书或授权委托书通常对学校入学和医疗决策有帮助。当地法律援助机构可以协助准备这些文件。"
      },
      "legalNext": {
        "title": "可能的后续法律步骤",
        "item1": "一些家庭在驱逐后探索法律选项，这些可能包括重新申请动议、上诉或困难豁免。这些程序通常有严格的时间期限。",
        "item2": "本页面不涵盖这些程序。本网站的案件指南和移民指导页面可以帮助了解这些程序通常涉及的内容。移民律师可以就是否适用于特定情况提供建议。",
        "item3": "移民法律援助：使用immigrationadvocates.org按地点查找免费或低收费的移民律师。"
      }
    },
